package com.bank.spark.service;

import com.bank.spark.model.TxnRecord;
import java.util.List;
import java.util.logging.Logger;

// Models relative serialized sizes for Java vs Kryo (registered / not).
// Real sizes come from Kryo/Java serializers; this illustrates the ratios.
public class SerializerSizer {

    private static final Logger log = Logger.getLogger(SerializerSizer.class.getName());

    // Approximate per-record overhead (bytes) for each strategy.
    private static final int JAVA_OVERHEAD = 180;       // class descriptors, reflection metadata
    private static final int KRYO_UNREG_OVERHEAD = 60;  // writes class NAME per object
    private static final int KRYO_REG_OVERHEAD = 20;    // writes small class ID per object
    private static final int PAYLOAD = 40;              // actual field bytes

    public long javaBytes(List<TxnRecord> batch) {
        long bytes = (long) batch.size() * (JAVA_OVERHEAD + PAYLOAD);
        log.warning(() -> "Java serialization: " + bytes + " bytes (large, slow)");
        return bytes;
    }

    public long kryoUnregisteredBytes(List<TxnRecord> batch) {
        long bytes = (long) batch.size() * (KRYO_UNREG_OVERHEAD + PAYLOAD);
        log.info(() -> "Kryo (unregistered): " + bytes + " bytes (writes class name)");
        return bytes;
    }

    public long kryoRegisteredBytes(List<TxnRecord> batch) {
        long bytes = (long) batch.size() * (KRYO_REG_OVERHEAD + PAYLOAD);
        log.info(() -> "Kryo (registered): " + bytes + " bytes (writes small class id)");
        return bytes;
    }
}
