package com.bank.spark;

import com.bank.spark.model.TxnRecord;
import com.bank.spark.service.SerializerSizer;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: compare serialized sizes across strategies.
public class SerializationDemo {

    private static final Logger log = Logger.getLogger(SerializationDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        SerializerSizer sizer = new SerializerSizer();

        // One million shuffle records of custom objects.
        List<TxnRecord> batch = new ArrayList<>();
        for (int i = 0; i < 1_000_000; i++) {
            batch.add(new TxnRecord("T" + i, "SAV2001", new BigDecimal("3000")));
        }

        long java = sizer.javaBytes(batch);
        long kryoUnreg = sizer.kryoUnregisteredBytes(batch);
        long kryoReg = sizer.kryoRegisteredBytes(batch);

        log.info(() -> "Kryo registered is " + (java / Math.max(1, kryoReg))
                + "x smaller than Java serialization");
        log.info("Serialization demo complete.");
    }
}
